MATCH (e:Escola)-[:LOCALIZADA_EM]->(:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio {nm_mun: 'Ubatuba'})
WHERE NOT EXISTS {
  MATCH (u:EquipamentoSaude)
  WHERE point.distance(e.location, u.location) <= 3000
}
RETURN m.nm_mun AS municipio, e.id_aparelho AS codigo, e.nm_aparelho AS escola

MATCH (m:Municipio)-[:PARTE_DE]->(:UF {nm_uf: 'São Paulo'})
WHERE NOT EXISTS {
  MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(:SetorCensitario)-[:PARTE_DE*3..4]->(m)
  WHERE u.at_01_conv_01 = true
}
RETURN m.nm_mun AS municipio

MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio {nm_mun: 'Teodoro Sampaio'})
WHERE NOT EXISTS {
  MATCH (e:Escola)
  WHERE point.distance(u.location, e.location) <= 2000
}
RETURN m.nm_mun AS municipio, u.id_aparelho AS codigo, u.nm_aparelho AS equipamento

MATCH (s:SetorCensitario)-[:PARTE_DE*2..3]->(d:Distrito)-[:PARTE_DE]->(m:Municipio {nm_mun: 'Piracicaba'})
WHERE NOT EXISTS { MATCH (:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) }
RETURN m.nm_mun AS municipio, d.nm_dist AS distrito, count(DISTINCT s) AS setores_sem_equipamento

MATCH (m:Municipio)-[:PARTE_DE]->(:UF {nm_uf: 'São Paulo'})
WHERE NOT EXISTS {
  MATCH (e:Escola)-[:LOCALIZADA_EM]->(:SetorCensitario)-[:PARTE_DE*3..4]->(m)
  WHERE e.tp_dependencia = 4
}
RETURN count(DISTINCT m) AS municipios_sem_escola_privada
